import"./hoisted.BUsU6o5h.js";const t=document.getElementById("contactForm"),o=t?.querySelector(".btn-submit"),e=document.getElementById("formMessage");t?.addEventListener("submit",async r=>{if(r.preventDefault(),!t.querySelector('[name="website"]')?.value){o?.classList.add("loading");try{await new Promise(s=>setTimeout(s,1500)),e&&(e.className="form-message success",e.textContent="Votre message a été envoyé avec succès. Nous vous répondrons dans les plus brefs délais."),t.reset()}catch{e&&(e.className="form-message error",e.textContent="Une erreur est survenue. Veuillez réessayer ou nous contacter directement par téléphone.")}finally{o?.classList.remove("loading")}}});
